using System.Collections.Generic;
using System.Linq;
class LSMTree {
    public SortedDictionary<string, string> memtable = new SortedDictionary<string, string>();
    public List<SortedDictionary<string, string>> sstables = new List<SortedDictionary<string, string>>();
    public void Put(string k, string v) {
        memtable[k] = v; if (memtable.Count >= 3) { sstables.Add(new SortedDictionary<string, string>(memtable)); memtable.Clear(); }
    }
    public string Get(string k) {
        if (memtable.ContainsKey(k)) return memtable[k];
        for (int i = sstables.Count - 1; i >= 0; i--) { if (sstables[i].ContainsKey(k)) return sstables[i][k]; }
        return null;
    }
}

using System.Collections.Generic;
class BTreeIndex {
    public List<string> keys = new List<string>();
    public List<string> values = new List<string>();
    public void Put(string k, string v) { keys.Add(k); values.Add(v); }
    public string Get(string k) { int idx = keys.IndexOf(k); return idx != -1 ? values[idx] : null; }
}

