using System.Collections.Generic;
using System.Linq;
interface IParticipant { bool Prepare(ulong tx); void Commit(ulong tx); void Abort(ulong tx); }
class Coordinator2PC {
    public List<IParticipant> participants;
    public string CommitTx(ulong tx) {
        if (participants.All(p => p.Prepare(tx))) { foreach (var p in participants) p.Commit(tx); return "Committed"; }
        foreach (var p in participants) p.Abort(tx); return "Aborted";
    }
}

using System.Collections.Generic;
class HashRouter {
    public List<string> nodes;
    public HashRouter(int n=3) { nodes = new List<string>(); for (int i=0; i<n; i++) nodes.Add($"Node-{i}"); }
    public string Route(string key) { int hash = 0; foreach (char c in key) hash = (hash * 31) + c; return nodes[Math.Abs(hash) % nodes.Count]; }
}

using System.Collections.Generic;
class RangeRouter {
    public List<(string start, string end, string node)> boundaries = new List<(string, string, string)>();
    public string Route(string key) {
        foreach (var b in boundaries) { if (key.CompareTo(b.start) >= 0 && key.CompareTo(b.end) <= 0) return b.node; }
        return "Node-Fallback";
    }
}

class ProtobufEncoder {
    public static byte[] EncodeField(uint tag, uint valType, byte[] value) {
        var res = new byte[value.Length + 1]; res[0] = (byte)((tag << 3) | valType); Array.Copy(value, 0, res, 1, value.Length); return res;
    }
}

class AvroEncoder {
    public static byte[] Encode(List<byte[]> fields) {
        var res = new List<byte>(); foreach (var f in fields) res.AddRange(f); return res.ToArray();
    }
}

using System.Collections.Generic;
class SingleLeaderDB {
    public Dictionary<string, string> leader = new Dictionary<string, string>();
    public List<Dictionary<string, string>> replicas = new List<Dictionary<string, string>>();
    public void Write(string k, string v) { leader[k] = v; foreach (var r in replicas) r[k] = v; }
    public string Read(string k) { return replicas[0][k]; }
}

using System.Collections.Generic;
class LeaderlessQuorum {
    public List<Dictionary<string, string>> store = new List<Dictionary<string, string>>();
    public void Write(string k, string v) { foreach (var r in store) r[k] = v; }
    public string Read(string k) { return store[0][k]; }
}

