class ListHead {
    public ListHead next, prev; public ListHead() { next = prev = this; }
    public static void ListAdd(ListHead newN, ListHead head) {
        var n = head.next; newN.next = n; newN.prev = head; head.next = newN; n.prev = newN;
    }
}

class LinuxKfifo<T> {
    public T[] buffer; public uint size, inIdx, outIdx;
    public LinuxKfifo(uint s) { size = s; buffer = new T[s]; }
    public bool Put(T val) { buffer[inIdx++ & (size - 1)] = val; return true; }
    public T Get() { return buffer[outIdx++ & (size - 1)]; }
}

